 dismissAssist(); if(!productOptions(p).length)return;optionDialog.innerHTML=`<div class="option-dialog-head"><h2 id="optionDialogTitle">لمستكِ، باختياركِ ♡</h2><button type="button" data-close-options aria-label="إغلاق خيارات المنتج">×</button></div><p class="option-dialog-name">${safe(pname(p))}</p><form>${optionFields(p,'dialog')}<button type="submit" class="btn">أضيفي اختياري للسلة · ${money(pprice(p))}</button></form>`;
