function refreshDetailRecommendations(){const el=$('#detailRecommendations'),p=el?find(el.dataset.relatedFor):null;if(!p)return;const cart=state.cart.some(x=>x.id===p.id)?state.cart:[...state.cart,{id:p.id,qty:1}],rows=recommendations(state.products,cart,{anchorId:p.id,promotions:state.promotions,limit:4});el.innerHTML=rows.length?`<hr class="detail-sep"/><h3>${tx('تفاصيل تكمّل اختياركِ ♡','A few complementary touches ♡')}</h3><p class="complement-intro">${tx('تصفّحي خطوات مختلفة تنسجم مع هذا المنتج.','Explore different care steps to complement this product.')}</p><div class="detail-complements">${rows.slice(0,3).map(({product:q,reason})=>`<article class="detail-complement" data-complement-type="${safe(productType(q))}"><a href="#/product/${q.id}"><img src="${safe(thumb(q))}" alt="${safe(pname(q))}" width="72" height="86" loading="lazy"/></a><div><a href="#/product/${q.id}"><b>${safe(pname(q))}</b></a><small>${safe(locale()==='en'?typeEnglish(productType(q))+' for your routine':reason)}</small><strong>${money(pprice(q))}</strong>${purchase(q)}</div></article>`).join('')}</div>`:'';const related=$('#relatedProducts');if(related)related.innerHTML=rows.map(({product:q})=>card(q)).join('')}
