function purchaseContent(p,mode='card'){
 const variant=activeVariant(p),options=productOptions(p),count=state.cart.find(x=>x.id===p.id&&(x.variant||'')===variant)?.qty||0,available=canBuy(p),cap=state.live?Math.min(10,stock(p)):10,label=choiceName(p,variant),suffix=label?'، '+label:'';
 const change=options.length&&mode==='card'?`<button type="button" class="variant-change" data-choose-option="${safe(p.id)}">${label?safe(label)+' · تغيير':'اختاري '+safe(optionLabel(p))}</button>`:'';
 if(!count)return `${change}<button class="${mode==='card'?'product-btn':'btn'}" data-add="${safe(p.id)}" ${!available?'disabled':''}>${available?(options.length&&!variant?'اختاري '+safe(optionLabel(p))+' +':tx('أضيفي للسلة +','Add to bag +')):tx('غير متوفر','Unavailable')}</button>`;
 return `${change}<span class="purchase-added">${ADDED_ICON}<span>${tx('تمت الإضافة إلى السلة','Added to bag')}</span></span><div class="cart-control" role="group" aria-label="كمية ${safe(pname(p)+suffix)}"><button class="cart-plus" data-add="${safe(p.id)}" aria-label="زيادة كمية ${safe(pname(p)+suffix)}" ${!available||totalQty(p.id)>=cap?'disabled':''}>+</button><output aria-live="polite">${count} ${tx('في السلة','in bag')}</output><button data-qty="${safe(p.id)}" data-variant="${safe(variant)}" data-step="-1" aria-label="تقليل كمية ${safe(pname(p)+suffix)}">−</button></div>`
}
