function add(id,amount=1,requested){const p=find(id);if(!p)return;const variant=requested??activeVariant(p);if(productOptions(p).length&&!selectedOption(p,variant)){openOptions(p);return}const current=state.cart.find(x=>x.id===id&&(x.variant||'')===variant);if(!current&&state.cart.length>=20){toast('يمكن إضافة 20 اختيارًا مختلفًا في الطلب الواحد');return}if(!canBuy(p)){toast('هذا المنتج غير متاح للطلب حاليًا');return}const limit=Math.max(0,(state.live?Math.min(10,stock(p)):10)-(totalQty(id)-(current?.qty||0))),count=nextQuantity(current?.qty||0,amount,limit,true);if(count<=(current?.qty||0)){toast('وصلتِ للكمية المتاحة من هذا المنتج، شامل درجاته');return}const addedQty=count-(current?.qty||0);state.selectedOptions[id]=variant;if(current)current.qty=count;else state.cart.push({id,qty:count,variant});saveCart();refreshCartViews();if(parseRoute().path!=='/checkout'&&$('#drawer').hidden)scheduleAssist(id);toast('تمت الإضافة إلى السلة'+(count>1?' · '+count+' من هذا الاختيار':''),true)}
