 const results=()=>{const {query:q}=parseRoute(),max=Number(q.get('max')||0),cat=q.get('cat')||'',b=q.get('brand')||'',sort=q.get('sort')||'featured';let list=searchProducts(state.products,q.get('q')||'').filter(p=>(!max||pprice(p)<=max)&&(!q.has('sale')||pdiscount(p)>0)&&(!cat||p.category===cat)&&(q.get('collection')!=='korean-care'||isKoreanCare(p))&&matchesBrand(p,b)&&matchesProductType(p,q.get('type')||'')&&(!q.has('new')||info(p).intakeBatch==='2026-10-27-b'));if(sort==='featured'&&!q.get('q'))list.sort(priorityCompare);if(sort==='price-asc')list.sort((a,b)=>pprice(a)-pprice(b));if(sort==='price-desc')list.sort((a,b)=>pprice(b)-pprice(a));if(sort==='discount')list.sort((a,b)=>pdiscount(b)-pdiscount(a));if(sort==='name')list.sort((a,b)=>pname(a).localeCompare(pname(b),locale()));$('#resultCount').textContent=`${list.length} منتج`;$('#productResults').innerHTML=list.length?`<div class="products-grid">${list.slice(0,state.displayCount).map(card).join('')}</div>${list.length>state.displayCount?'<button class="btn btn-light loadmore" id="loadMore">عرض المزيد</button>':''}`:'<div class="empty"><span class="empty-icon">♡</span><p>لم نعثر على منتجات بهذه المواصفات.</p><a href="#/shop" class="btn btn-light">عرض الكل</a></div>';if($('#loadMore'))$('#loadMore').onclick=()=>{state.displayCount+=24;results()}};
