 mountProductStory(app,{profile,images:productGallery(p,state.galleries),bundles:productOffers(p),product:p,name:pname(p),image:largeImageFor(p,p.image||p.image_url,state.thumbnails),cap:canBuy(p)?(state.live?Math.min(10,stock(p)):10):0,live:state.live,quantity:totalQty(p.id)||1,inBag:totalQty(p.id),hasOtherItems:state.cart.some(x=>x.id!==p.id),promotions:state.promotions,taxonomy:productTaxonomy(p),brand:brandLink(p,'detail-brand'),onCheckout:quantity=>{if(setSelection(quantity))openQuickCheckout()},onAdd:quantity=>{if(!setSelection(quantity))return false;toast(tx('تمت الإضافة إلى السلة','Added to bag'),true);scheduleAssist(p.id);return true},onZoom:(images,name,index)=>{dismissAssist();imageZoom.open(images,name,index)},onShare:()=>{dismissAssist();productShare.open(p,pname(p))}});
 mountProductVideos($('[data-product-videos]',app),{productId:p.id});
 refreshDetailRecommendations();
